-- 2026-10 URL 终态迁移:/post/<id>-<slug> 混合形态(arch/07-frontend §2 修订)
-- 1) slug 列可空(纯装饰 ASCII;id 是唯一解析锚)
-- 2) 156 篇文章 slug 由 percent-encoded 中文 → 标题 ASCII token(快照 2026-10-03;
--    含 53 篇已下架删除文——生产不可见,统一形态防环境差异)
-- 3) legacy_url_map 补 103×301(旧单段链 → 新形态,带尾斜杠)与 53×410(下架删除,2026-10-03);
--    幂等:ON CONFLICT (old_path) 覆盖(含 WP 切换期遗留行)

-- 1. slug 可空
ALTER TABLE "content_post" ALTER COLUMN "slug" DROP NOT NULL;

-- 2. 全量文章 → ASCII slug(纯中文标题 → NULL,canonical 走 bare-id /post/<id>/)
UPDATE "content_post" AS p SET "slug" = v.slug
